import { GoogleGenAI } from "@google/genai";
import { Coordinates, AnalysisResult } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const analyzeResults = async (coords: Coordinates): Promise<AnalysisResult> => {
  try {
    const model = 'gemini-2.5-flash';

    const prompt = `
      You are a political science expert capable of analyzing political compass results.

      The user has the following coordinates on the political compass:
      Economic Axis (X): ${coords.x.toFixed(2)} (Range: -10 Left to +10 Right)
      Social Axis (Y): ${coords.y.toFixed(2)} (Range: -10 Libertarian to +10 Authoritarian)

      Please provide a brief analysis in HEBREW (עברית).
      Return the response in strict JSON format with the following structure:
      {
        "title": "A short title for their position (e.g., 'סוציאל-דמוקרט', 'ליברל קלאסי', etc.)",
        "description": "A 2-3 sentence explanation of what this position means regarding their views on economy and society.",
        "ideology": "Name of the closest political ideology or famous figure associated with this quadrant."
      }
      Do not include markdown code blocks. Just the raw JSON string.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return JSON.parse(text) as AnalysisResult;
  } catch (error) {
    console.error("Error analyzing results:", error);
    return {
      title: "שגיאה בניתוח",
      description: "לא הצלחנו לנתח את התוצאות כרגע באמצעות הבינה המלאכותית. עם זאת, המיקום שלך במפה מדויק.",
      ideology: "לא ידוע"
    };
  }
};

