import React, { useState } from 'react';
import { Question, Answer } from '../types';
import { QUESTIONS } from '../constants';
import { ArrowLeft, ArrowRight, Check } from 'lucide-react';

interface QuizProps {
  onComplete: (answers: Answer[]) => void;
}

const Quiz: React.FC<QuizProps> = ({ onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [animating, setAnimating] = useState(false);

  const currentQuestion = QUESTIONS[currentIndex];

  const handleAnswer = (score: number) => {
    const newAnswer: Answer = { questionId: currentQuestion.id, score };
    const updatedAnswers = [...answers, newAnswer];

    setAnimating(true);

    setTimeout(() => {
      if (currentIndex < QUESTIONS.length - 1) {
        setAnswers(updatedAnswers);
        setCurrentIndex(prev => prev + 1);
        setAnimating(false);
      } else {
        onComplete(updatedAnswers);
      }
    }, 300);
  };

  const progress = ((currentIndex + 1) / QUESTIONS.length) * 100;

  return (
    <div className="max-w-2xl mx-auto w-full px-4">
      {/* Progress Bar */}
      <div className="mb-8">
        <div className="flex justify-between text-sm text-slate-500 mb-2 font-medium">
          <span>שאלה {currentIndex + 1} מתוך {QUESTIONS.length}</span>
          <span>{Math.round(progress)}%</span>
        </div>
        <div className="h-3 w-full bg-slate-200 rounded-full overflow-hidden">
          <div 
            className="h-full bg-indigo-600 transition-all duration-500 ease-out rounded-full"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* Question Card */}
      <div className={`transform transition-all duration-300 ${animating ? 'opacity-0 translate-x-10' : 'opacity-100 translate-x-0'}`}>
        <div className="bg-white rounded-2xl shadow-lg p-8 mb-8 border border-slate-100 min-h-[300px] flex flex-col justify-center items-center text-center">
          <h2 className="text-2xl md:text-3xl font-bold text-slate-800 mb-8 leading-relaxed">
            {currentQuestion.text}
          </h2>
        </div>

        {/* Answer Buttons */}
        <div className="grid grid-cols-1 md:grid-cols-5 gap-3">
          <button 
            onClick={() => handleAnswer(2)}
            className="py-4 px-2 rounded-xl bg-green-700 text-white font-bold hover:bg-green-800 transition-colors shadow-sm hover:shadow-md flex flex-col items-center justify-center gap-1"
          >
            <span className="text-lg">מסכים בהחלט</span>
            <Check className="w-6 h-6" />
          </button>

          <button 
            onClick={() => handleAnswer(1)}
            className="py-4 px-2 rounded-xl bg-green-500 text-white font-semibold hover:bg-green-600 transition-colors shadow-sm hover:shadow-md"
          >
            מסכים
          </button>

          <button 
            onClick={() => handleAnswer(0)}
            className="py-4 px-2 rounded-xl bg-slate-200 text-slate-700 font-medium hover:bg-slate-300 transition-colors shadow-sm hover:shadow-md"
          >
            ניטרלי
          </button>

          <button 
            onClick={() => handleAnswer(-1)}
            className="py-4 px-2 rounded-xl bg-red-400 text-white font-semibold hover:bg-red-500 transition-colors shadow-sm hover:shadow-md"
          >
            לא מסכים
          </button>

          <button 
            onClick={() => handleAnswer(-2)}
            className="py-4 px-2 rounded-xl bg-red-700 text-white font-bold hover:bg-red-800 transition-colors shadow-sm hover:shadow-md flex flex-col items-center justify-center gap-1"
          >
            <span className="text-lg">מתנגד בהחלט</span>
             {/* Using double text or icon to signify strong disagreement */}
             <span className="text-2xl leading-none">×</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default Quiz;

import React, { useEffect, useState } from 'react';
import { Coordinates, AnalysisResult } from '../types';
import CompassChart from './CompassChart';
import { analyzeResults } from '../services/geminiService';
import { RefreshCw, Share2, Sparkles } from 'lucide-react';

interface ResultViewProps {
  coordinates: Coordinates;
  onRetake: () => void;
}

