export default ResultView;

import React, { useState } from 'react';
import Quiz from './components/Quiz';
import ResultView from './components/ResultView';
import { Answer, Coordinates, Question, Axis } from './types';
import { QUESTIONS } from './constants';
import { Compass } from 'lucide-react';

enum AppState {
  WELCOME,
  QUIZ,
  RESULTS
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [coordinates, setCoordinates] = useState<Coordinates>({ x: 0, y: 0 });

  const calculateResults = (answers: Answer[]) => {
    let econScore = 0;
    let socialScore = 0;

    // Max possible score per axis: 2 (max score) * number of questions per axis
    // We normalize this to -10 to +10

    // Count questions per axis
    const econQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.ECONOMIC).length;
    const socialQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.SOCIAL).length;

    answers.forEach(ans => {
      const question = QUESTIONS.find(q => q.id === ans.questionId);
      if (!question) return;

      const impact = ans.score * question.direction;

      if (question.axis === Axis.ECONOMIC) {
        econScore += impact;
      } else {
        socialScore += impact;
      }
    });

    // Normalize to range -10 to 10
    // Current range is [-2 * count, 2 * count]
    // Normalized = (current / (2 * count)) * 10

    const normalizedX = (econScore / (2 * econQuestionsCount)) * 10;
    const normalizedY = (socialScore / (2 * socialQuestionsCount)) * 10;

    setCoordinates({ x: normalizedX, y: normalizedY });
    setAppState(AppState.RESULTS);
  };

  const handleStart = () => {
    setAppState(AppState.QUIZ);
  };

  const handleRetake = () => {
    setAppState(AppState.WELCOME);
    setCoordinates({ x: 0, y: 0 });
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans" dir="rtl">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 text-indigo-700">
            <Compass className="w-8 h-8" strokeWidth={1.5} />
            <h1 className="text-xl font-bold tracking-tight">המצפן הפוליטי</h1>
          </div>
          <div className="text-sm text-slate-500 hidden sm:block">
            גלה את מקומך במפה הפוליטית
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col items-center justify-center py-8">
        {appState === AppState.WELCOME && (
          <div className="max-w-xl mx-auto px-4 text-center animate-fadeIn">
            <div className="bg-white p-8 rounded-2xl shadow-xl border border-slate-100">
              <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-6">
                <Compass className="w-10 h-10 text-indigo-600" />
              </div>
              <h2 className="text-3xl font-bold text-slate-900 mb-4">ברוכים הבאים למצפן הפוליטי</h2>
              <p className="text-lg text-slate-600 mb-8 leading-relaxed">
                מבחן זה ינתח את העמדות שלך בנושאים כלכליים וחברתיים וימקם אותך על המפה הפוליטית.
                <br className="hidden md:block" />
                בסיום, הבינה המלאכותית שלנו תספק ניתוח מעמיק של התוצאות.
              </p>

              <div className="space-y-4">
                <div className="flex items-center justify-center gap-2 text-sm text-slate-500 mb-6">
                  <span className="bg-slate-100 px-3 py-1 rounded-full">{QUESTIONS.length} שאלות</span>
                  <span className="bg-slate-100 px-3 py-1 rounded-full">כ-2 דקות</span>
                </div>

                <button 
                  onClick={handleStart}
                  className="w-full sm:w-auto px-8 py-4 bg-indigo-600 text-white text-lg font-bold rounded-xl hover:bg-indigo-700 transition-all hover:scale-105 shadow-lg shadow-indigo-200"
                >
                  התחל במבחן
                </button>
              </div>
            </div>
            <p className="mt-8 text-xs text-slate-400">
              הנתונים אינם נשמרים. הניתוח מתבצע בזמן אמת באמצעות Gemini AI.
            </p>
          </div>
        )}

        {appState === AppState.QUIZ && (
          <Quiz onComplete={calculateResults} />
        )}

        {appState === AppState.RESULTS && (
          <ResultView coordinates={coordinates} onRetake={handleRetake} />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 py-6 mt-auto">
        <div className="max-w-5xl mx-auto px-4 text-center text-slate-400 text-sm">
          <p>© {new Date().getFullYear()} המצפן הפוליטי | מבוסס על מודל Gemini</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

export enum Axis {
  ECONOMIC = 'economic', // X-axis: -10 (Left) to +10 (Right)
  SOCIAL = 'social',     // Y-axis: -10 (Libertarian) to +10 (Authoritarian)
}

export interface Question {
  id: number;
  text: string;
  axis: Axis;
  direction: 1 | -1; // 1 means Agreement moves towards Positive (Right/Auth), -1 means Agreement moves towards Negative (Left/Lib)
}

export interface Answer {
  questionId: number;
  score: number; // -2 (Strongly Disagree) to +2 (Strongly Agree)
}

export interface Coordinates {
  x: number;
  y: number;
}

export interface AnalysisResult {
  title: string;
  description: string;
  ideology: string;
}

export interface SavedResult {
  coordinates: Coordinates;
  analysis: AnalysisResult;
  timestamp: number;
}

import { SavedResult } from '../types';

const STORAGE_KEY = 'political_compass_result_v1';

export const saveResult = (result: SavedResult): void => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(result));
  } catch (error) {
    console.error('Failed to save result:', error);
  }
};

export const getSavedResult = (): SavedResult | null => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    if (!data) return null;
    return JSON.parse(data) as SavedResult;
  } catch (error) {
    console.error('Failed to load result:', error);
    return null;
  }
};

export const hasSavedResult = (): boolean => {
  return !!localStorage.getItem(STORAGE_KEY);
};

export const clearSavedResult = (): void => {
  localStorage.removeItem(STORAGE_KEY);
};

import React, { useEffect, useState } from 'react';
import { Coordinates, AnalysisResult } from '../types';
import CompassChart from './CompassChart';
import { analyzeResults } from '../services/geminiService';
import { RefreshCw, Share2, Sparkles } from 'lucide-react';

interface ResultViewProps {
  coordinates: Coordinates;
  onRetake: () => void;
  initialAnalysis?: AnalysisResult | null;
  onAnalysisComplete?: (analysis: AnalysisResult) => void;
}

const ResultView: React.FC<ResultViewProps> = ({ 
  coordinates, 
  onRetake, 
  initialAnalysis = null, 
  onAnalysisComplete 
}) => {
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(initialAnalysis);
  const [loading, setLoading] = useState(!initialAnalysis);

  useEffect(() => {
    // If we have an initial analysis (e.g. from history), use it and don't fetch
    if (initialAnalysis) {
      setAnalysis(initialAnalysis);
      setLoading(false);
      return;
    }

    let isMounted = true;
    const fetchAnalysis = async () => {
      setLoading(true);
      const result = await analyzeResults(coordinates);
      if (isMounted) {
        setAnalysis(result);
        setLoading(false);
        if (onAnalysisComplete) {
          onAnalysisComplete(result);
        }
      }
    };
    fetchAnalysis();
    return () => { isMounted = false; };
  }, [coordinates, initialAnalysis]); // Re-run if coordinates change or initialAnalysis changes

  return (
    <div className="max-w-4xl mx-auto w-full px-4 py-8 animate-fadeIn">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-bold text-slate-900 mb-2">התוצאות שלך</h2>
        <p className="text-slate-500">הנה המיקום שלך על המצפן הפוליטי</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-10">
        <div className="flex flex-col">
          <CompassChart coordinates={coordinates} />
          <div className="mt-4 flex justify-center gap-4 text-sm text-slate-600">
            <span className="px-3 py-1 bg-slate-100 rounded-full">
              כלכלי: {coordinates.x > 0 ? 'ימין' : 'שמאל'} ({Math.abs(coordinates.x).toFixed(1)})
            </span>
            <span className="px-3 py-1 bg-slate-100 rounded-full">
               חברתי: {coordinates.y > 0 ? 'סמכותני' : 'ליברלי'} ({Math.abs(coordinates.y).toFixed(1)})
            </span>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-lg border border-indigo-100 p-6 flex flex-col relative overflow-hidden">
          <div className="absolute top-0 right-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"></div>

          <div className="flex items-center gap-2 mb-4 text-indigo-700">
            <Sparkles className="w-5 h-5" />
            <h3 className="font-bold text-lg">ניתוח AI</h3>
          </div>

          {loading ? (
            <div className="flex-1 flex flex-col items-center justify-center text-slate-400 space-y-4">
              <RefreshCw className="w-8 h-8 animate-spin" />
              <p>מנתח את התוצאות שלך...</p>
            </div>
          ) : analysis ? (
            <div className="space-y-4 animate-fadeIn">
              <div>
                <span className="text-xs font-semibold tracking-wider text-slate-400 uppercase">כותרת</span>
                <h4 className="text-2xl font-bold text-slate-800">{analysis.title}</h4>
              </div>

              <div>
                <span className="text-xs font-semibold tracking-wider text-slate-400 uppercase">הסבר</span>
                <p className="text-slate-600 leading-relaxed mt-1">
                  {analysis.description}
                </p>
              </div>

              <div className="bg-slate-50 p-4 rounded-lg border border-slate-100">
                <span className="text-xs font-semibold tracking-wider text-slate-400 uppercase">קרבה רעיונית</span>
                <p className="text-indigo-600 font-medium mt-1">{analysis.ideology}</p>
              </div>
            </div>
          ) : (
            <div className="text-red-500">שגיאה בטעינת הנתונים</div>
          )}
        </div>
      </div>

      <div className="flex justify-center gap-4">
        <button 
          onClick={onRetake}
          className="flex items-center gap-2 px-6 py-3 rounded-full bg-slate-800 text-white font-medium hover:bg-slate-900 transition-all hover:scale-105"
        >
          <RefreshCw className="w-4 h-4" />
          התחל מחדש
        </button>
      </div>
    </div>
  );
};

