import React, { useState, useEffect } from 'react';
import { Question, Answer } from '../types';
import { QUESTIONS } from '../constants';
import { ArrowLeft, ArrowRight, Check, ChevronRight } from 'lucide-react';

interface QuizProps {
  onComplete: (answers: Answer[]) => void;
}

const Quiz: React.FC<QuizProps> = ({ onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [animating, setAnimating] = useState(false);
  const [direction, setDirection] = useState<'forward' | 'backward'>('forward');

  // Ensure currentIndex is valid
  const currentQuestion = QUESTIONS[currentIndex] || QUESTIONS[0];

  const handleAnswer = (score: number) => {
    if (animating) return; // Prevent double clicks

    const newAnswer: Answer = { questionId: currentQuestion.id, score };

    // Create a copy of answers to modify
    const updatedAnswers = [...answers];
    // Update or insert the answer at the current index
    updatedAnswers[currentIndex] = newAnswer;

    setAnswers(updatedAnswers);
    setDirection('forward');
    setAnimating(true);

    setTimeout(() => {
      if (currentIndex < QUESTIONS.length - 1) {
        setCurrentIndex(prev => prev + 1);
        setAnimating(false);
      } else {
        // Last question - call onComplete
        // Note: We don't set animating(false) here because the component should unmount.
        // If it doesn't unmount due to parent error, we might be stuck hidden.
        try {
          onComplete(updatedAnswers);
        } catch (e) {
          console.error("Error completing quiz:", e);
          setAnimating(false); // Restore UI if error occurs
        }
      }
    }, 250);
  };

  const handleBack = () => {
    if (currentIndex > 0 && !animating) {
      setDirection('backward');
      setAnimating(true);
      setTimeout(() => {
        setCurrentIndex(prev => prev - 1);
        setAnimating(false);
      }, 250);
    }
  };

  // Safe progress calculation
  const progress = Math.min(100, Math.round(((currentIndex + 1) / QUESTIONS.length) * 100));

  return (
    <div className="max-w-3xl mx-auto w-full px-4">
      {/* Progress Bar */}
      <div className="mb-8">
        <div className="flex justify-between items-end text-sm text-slate-400 mb-3 font-medium">
          <div className="flex flex-col">
            <span className="text-xs text-slate-500 uppercase tracking-wider mb-1">התקדמות</span>
            <span className="text-xl font-bold text-yellow-400">שאלה {currentIndex + 1} <span className="text-slate-600 text-base font-normal">/ {QUESTIONS.length}</span></span>
          </div>
          <div className="bg-slate-800 px-3 py-1 rounded-full shadow-sm border border-slate-700 text-slate-300">
             {progress}%
          </div>
        </div>
        <div className="h-4 w-full bg-slate-800 rounded-full overflow-hidden border border-slate-700">
          <div 
            className="h-full bg-yellow-400 transition-all duration-500 ease-out rounded-full shadow-[0_0_10px_rgba(250,204,21,0.5)]"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* Question Card */}
      <div className={`transform transition-all duration-300 ease-out ${
          animating 
            ? (direction === 'forward' ? 'opacity-0 -translate-x-10' : 'opacity-0 translate-x-10') 
            : 'opacity-100 translate-x-0'
        }`}>
        <div className="bg-slate-900/80 backdrop-blur-xl rounded-3xl shadow-xl p-8 md:p-12 mb-8 border border-slate-800 min-h-[280px] flex flex-col justify-center items-center text-center relative overflow-hidden group">
           {/* Subtle background decoration */}
           <div className="absolute top-0 right-0 w-32 h-32 bg-yellow-500/5 rounded-bl-full -mr-10 -mt-10 transition-transform group-hover:scale-110"></div>
           <div className="absolute bottom-0 left-0 w-24 h-24 bg-slate-700/10 rounded-tr-full -ml-8 -mb-8 transition-transform group-hover:scale-110"></div>

           <h2 className="text-2xl md:text-3xl font-bold text-slate-100 leading-relaxed z-10">
            {currentQuestion.text}
          </h2>
        </div>

        {/* Answer Buttons */}
        <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
          <button 
            onClick={() => handleAnswer(2)}
            disabled={animating}
            className="group relative py-4 px-2 rounded-2xl bg-green-600 text-white font-bold hover:bg-green-500 transition-all shadow-lg shadow-black/20 hover:-translate-y-1 active:scale-95 flex flex-col items-center justify-center gap-1 overflow-hidden border border-green-500 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
          >
            <span className="text-lg relative z-10">מסכים בהחלט</span>
            <Check className="w-6 h-6 relative z-10" />
          </button>

          <button 
            onClick={() => handleAnswer(1)}
            disabled={animating}
            className="py-4 px-2 rounded-2xl bg-slate-800 border-2 border-green-600 text-green-500 font-bold hover:bg-slate-700 transition-all shadow-md hover:-translate-y-1 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
          >
            מסכים
          </button>

          <button 
            onClick={() => handleAnswer(0)}
            disabled={animating}
            className="py-4 px-2 rounded-2xl bg-slate-800 border-2 border-slate-600 text-slate-400 font-bold hover:bg-slate-700 transition-all shadow-md hover:-translate-y-1 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
          >
            ניטרלי
          </button>

          <button 
            onClick={() => handleAnswer(-1)}
            disabled={animating}
            className="py-4 px-2 rounded-2xl bg-slate-800 border-2 border-red-600 text-red-500 font-bold hover:bg-slate-700 transition-all shadow-md hover:-translate-y-1 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
          >
            לא מסכים
          </button>

          <button 
            onClick={() => handleAnswer(-2)}
            disabled={animating}
            className="group relative py-4 px-2 rounded-2xl bg-red-600 text-white font-bold hover:bg-red-500 transition-all shadow-lg shadow-black/20 hover:-translate-y-1 active:scale-95 flex flex-col items-center justify-center gap-1 overflow-hidden border border-red-500 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
          >
            <span className="text-lg relative z-10">מתנגד בהחלט</span>
             <span className="text-2xl leading-none relative z-10">×</span>
          </button>
        </div>

        {/* Navigation Controls */}
        <div className="mt-8 flex justify-between items-center px-2">
            <button
                onClick={handleBack}
                disabled={currentIndex === 0 || animating}
                className={`flex items-center gap-2 px-4 py-2 rounded-xl font-medium transition-all ${
                    currentIndex === 0 || animating
                    ? 'text-slate-700 cursor-not-allowed' 
                    : 'text-slate-400 hover:text-yellow-400 hover:bg-slate-800'
                }`}
            >
                <ChevronRight className="w-5 h-5 rotate-180" /> 
                <span>חזור לשאלה הקודמת</span>
            </button>
        </div>

      </div>
    </div>
  );
};

export default Quiz;

import { GoogleGenAI, Type } from "@google/genai";
import { Coordinates, AnalysisResult } from "../types";

// Fallback logic for when API key is missing or calls fail
const getFallbackAnalysis = (coords: Coordinates): AnalysisResult => {
  const { x, y } = coords;
  let title = "";
  let ideology = "";
  let description = "";

  // Logic:
  // X: -10 (Left/Socialist) to +10 (Right/Capitalist)
  // Y: -10 (Libertarian/Dove) to +10 (Authoritarian/Hawk)

  if (x < 0 && y < 0) {
    title = "שמאל-ליברלי (שמאל ציוני)";
    ideology = "העבודה / מרצ / הדמוקרטים";
    description = "אתה תומך במדיניות רווחה כלכלית וצמצום פערים, לצד עמדות ליברליות מובהקות בנושאי דת ומדינה, זכויות אדם ופתרון מדיני. אתה מאמין בשוויון אזרחי מלא ובחשיבות מערכת המשפט.";
  } else if (x < 0 && y >= 0) {
    title = "שמאל חברתי-שמרני";
    ideology = "שמאל מסורתי / מפלגות חברתיות";
    description = "אתה תומך במעורבות ממשלתית עמוקה בכלכלה ובביטחון סוציאלי, אך מחזיק בעמדות שמרניות יותר בנושאי ביטחון, לאום או מסורת. אתה מעדיף יציבות חברתית על פני ליברליזם רדיקלי.";
  } else if (x >= 0 && y < 0) {
    title = "ימין-ליברלי (ליברליזם קלאסי)";
    ideology = "יש עתיד / תקווה חדשה / גישה ליברלית בליכוד";
    description = "אתה מאמין בשוק חופשי, הפחתת מיסים ויוזמה פרטית, אך מדגיש גם את חשיבותן של זכויות הפרט, שלטון החוק והפרדת רשויות. אתה נוטה לפרגמטיות מדינית.";
  } else { // x >= 0 && y >= 0
    title = "ימין-שמרני (המחנה הלאומי)";
    ideology = "הליכוד / הציונות הדתית / ש\"ס";
    description = "אתה דוגל בערכים לאומיים ומסורתיים, עמדה ביטחונית תקיפה וחיזוק המשילות. מבחינה כלכלית אתה נוטה לשוק חופשי, אך רואה חשיבות בשמירה על האופי היהודי של המדינה.";
  }

  return {
    title,
    description: description + "\n\n(הערה: תוצאה זו נוצרה באופן אוטומטי מכיוון שלא זוהה חיבור פעיל לשירות הבינה המלאכותית).",
    ideology
  };
};

export const analyzeResults = async (coords: Coordinates): Promise<AnalysisResult> => {
  try {
    const apiKey = process.env.API_KEY;

    // Immediate fallback if no key is configured
    if (!apiKey) {
      console.warn("API Key is missing, using fallback analysis.");
      return getFallbackAnalysis(coords);
    }

    const ai = new GoogleGenAI({ apiKey });
    const model = 'gemini-2.5-flash';

    // In Israeli context:
    // X Axis: Economic Left (Socialism/Labor) <-> Economic Right (Capitalism/Likud/Libertarian)
    // Y Axis: Social Liberal/Dove (Meretz/Yesh Atid) <-> Social Authoritarian/Hawk/Religious (Religious Zionism/Shas/Likud)

    const prompt = `
      You are an expert political analyst specializing in ISRAELI POLITICS (פוליטיקה ישראלית).

      The user has completed a political compass test adapted for Israel.
      Their coordinates are:
      Economic Axis (X): ${coords.x.toFixed(2)} (Range: -10 Socialist Left to +10 Capitalist Right)
      Social/Security Axis (Y): ${coords.y.toFixed(2)} (Range: -10 Liberal/Secular/Dove to +10 Conservative/Religious/Hawk)

      Based on these coordinates, provide a detailed analysis in HEBREW.

      You must return the response in strict JSON format with the following structure:
      {
        "title": "A short, catchy title defining their political identity (e.g., 'ימין ליברלי', 'שמאל סוציאל-דמוקרטי', 'מרכז קלאסי', 'ימין מסורתי', etc.)",
        "description": "A 2-3 sentence analysis explaining their position. Relate to key Israeli issues like the economy, religion & state, and security/Supreme Court.",
        "ideology": "The closest Israeli political parties or ideological streams (e.g., 'העבודה / מרצ', 'יש עתיד / המחנה הממלכתי', 'הליכוד', 'הציונות הדתית', 'ישראל ביתנו'). Choose the best fit."
      }
      Do not include markdown code blocks. Just the raw JSON string.
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            ideology: { type: Type.STRING },
          },
          required: ["title", "description", "ideology"],
        },
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return JSON.parse(text) as AnalysisResult;
  } catch (error) {
    console.error("Error analyzing results with AI:", error);
    // If AI fails (quota, network, invalid key), return fallback
    return getFallbackAnalysis(coords);
  }
};

import React, { useState, useEffect } from 'react';
import Quiz from './components/Quiz';
import ResultView from './components/ResultView';
import { Answer, Coordinates, AnalysisResult, Axis } from './types';
import { QUESTIONS } from './constants';
import { Compass, History, BrainCircuit, HeartHandshake, Moon, Sun } from 'lucide-react';
import { getSavedResult, saveResult, hasSavedResult } from './utils/storage';

enum AppState {
  WELCOME,
  QUIZ,
  RESULTS
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.WELCOME);
  const [coordinates, setCoordinates] = useState<Coordinates>({ x: 0, y: 0 });
  const [currentAnalysis, setCurrentAnalysis] = useState<AnalysisResult | null>(null);
  const [hasHistory, setHasHistory] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false); // Default to Light Mode

  useEffect(() => {
    setHasHistory(hasSavedResult());

    // Check system preference or default to light
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
       // Optional: Uncomment to respect system preference initially
       // setIsDarkMode(true);
    }
  }, []);

  // Handle Theme Toggle
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const calculateResults = (answers: Answer[]) => {
    try {
      let econScore = 0;
      let socialScore = 0;

      const econQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.ECONOMIC).length || 1;
      const socialQuestionsCount = QUESTIONS.filter(q => q.axis === Axis.SOCIAL).length || 1;

      answers.forEach(ans => {
        const question = QUESTIONS.find(q => q.id === ans.questionId);
        if (!question) return;

        const score = Number(ans.score);
        const direction = Number(question.direction);

        if (isNaN(score) || isNaN(direction)) return;

        const impact = score * direction;

        if (question.axis === Axis.ECONOMIC) {
          econScore += impact;
        } else {
          socialScore += impact;
        }
      });

      const normalizedX = (econScore / (2 * econQuestionsCount)) * 10;
      const normalizedY = (socialScore / (2 * socialQuestionsCount)) * 10;

      const safeX = Math.max(-10, Math.min(10, normalizedX || 0));
      const safeY = Math.max(-10, Math.min(10, normalizedY || 0));

      setCoordinates({ x: safeX, y: safeY });
      setCurrentAnalysis(null);
      setAppState(AppState.RESULTS);
    } catch (error) {
      console.error("Error calculating results:", error);
      setAppState(AppState.WELCOME);
    }
  };

  const handleAnalysisComplete = (analysis: AnalysisResult) => {
    saveResult({
      coordinates,
      analysis,
      timestamp: Date.now()
    });
    setHasHistory(true);
  };

  const handleLoadHistory = () => {
    const saved = getSavedResult();
    if (saved) {
      setCoordinates(saved.coordinates);
      setCurrentAnalysis(saved.analysis);
      setAppState(AppState.RESULTS);
    }
  };

  const handleStart = () => {
    setAppState(AppState.QUIZ);
  };

  const handleRetake = () => {
    setAppState(AppState.WELCOME);
    setCoordinates({ x: 0, y: 0 });
    setCurrentAnalysis(null);
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300" dir="rtl">
      {/* Header */}
      <header className="bg-white/80 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-50 glass transition-colors duration-300">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div 
            className="flex items-center gap-3 cursor-pointer group" 
            onClick={() => setAppState(AppState.WELCOME)}
          >
            <div className="bg-yellow-400 text-slate-950 p-1.5 rounded-lg shadow-[0_0_15px_rgba(250,204,21,0.3)] group-hover:scale-110 transition-transform">
                <Compass className="w-6 h-6" strokeWidth={2.5} />
            </div>
            <div>
                <h1 className="text-xl font-black tracking-tight leading-none text-slate-900 dark:text-slate-100">המצפן הפוליטי</h1>
                <span className="text-xs text-yellow-500 dark:text-yellow-400 font-bold tracking-wider">פרוייקט דעת</span>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {/* Theme Toggle */}
             <button 
              onClick={toggleTheme}
              className="p-2 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
              aria-label="Toggle Theme"
             >
                {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
             </button>

            <div className="hidden md:flex items-center gap-2 text-xs font-medium text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-900/50 px-3 py-1 rounded-full border border-slate-200 dark:border-slate-800">
                <span>פותח ע"י חגי הראל</span>
                <span className="w-1 h-1 bg-slate-400 dark:bg-slate-600 rounded-full"></span>
                <span>מופעל ע"י Gemini AI</span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col items-center justify-center py-8 relative overflow-hidden">
