כדי שהנתונים החדשים יישמרו, אתה **חייב** להחליף את הקוד ב-Google Apps Script בקוד המעודכן הזה, ואז לבצע **Deploy > New Version** מחדש!

```javascript
function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();

    // וודא שהשורה הראשונה בגיליון מכילה את הכותרות:
    // A: Timestamp, B: X, C: Y, D: Title, E: Description, F: UserAgent, G: Duration, H: Answers, I: ScreenRes

    var rawData = e.postData.contents;
    var data = JSON.parse(rawData);

    sheet.appendRow([
      data.timestamp,
      data.x,
      data.y,
      data.title,
      data.description,
      data.userAgent,
      data.duration,       // משך זמן בשניות
      data.answers,        // רשימת התשובות (למשל "1:2, 2:-1")
      data.screenResolution // רזולוציית מסך
    ]);

    return ContentService.createTextOutput(JSON.stringify({ 'result': 'success' }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ 'result': 'error', 'error': error.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}
