        </div>

        {/* Point Annotation */}
        <div className="absolute bottom-1 right-2 text-[9px] text-slate-400 dark:text-slate-500 font-mono">
           ({coordinates.x.toFixed(1)}, {coordinates.y.toFixed(1)})
        </div>
      </div>
    </div>
  );
};

