import React, { useEffect, useState, useRef } from 'react';
import { Coordinates, AnalysisResult, Answer } from '../types';
import CompassChart from './CompassChart';
import { analyzeResults } from '../services/geminiService';
import { reportResult } from '../services/reportingService';
import { RefreshCw, Sparkles, AlertCircle, Share2, Check, Download } from 'lucide-react';
import html2canvas from 'html2canvas';

interface ResultViewProps {
  coordinates: Coordinates;
  onRetake: () => void;
  initialAnalysis?: AnalysisResult | null;
  onAnalysisComplete?: (analysis: AnalysisResult) => void;
  isDarkMode?: boolean;
  isAccessible?: boolean;
  // Analytics and User Data
  quizDuration?: number;
  answers?: Answer[];
  userName?: string;
  userEmail?: string;
}

const ResultView: React.FC<ResultViewProps> = ({ 
  coordinates, 
  onRetake, 
  initialAnalysis = null, 
  onAnalysisComplete,
  isDarkMode = false,
  isAccessible = false,
  quizDuration = 0,
  answers = [],
  userName = "Anonymous",
  userEmail = ""
}) => {
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(initialAnalysis);
  const [loading, setLoading] = useState(!initialAnalysis);
  const [copied, setCopied] = useState(false);
  const [downloading, setDownloading] = useState(false);

  const resultRef = useRef<HTMLDivElement>(null);

  // Use a ref to ensure we only report once per mounting/calculation
  const hasReportedRef = useRef(false);

  useEffect(() => {
    // If we loaded from history (initialAnalysis exists), we don't report again.
    if (initialAnalysis) {
      setAnalysis(initialAnalysis);
      setLoading(false);
      return;
    }

    let isMounted = true;
    const fetchAnalysis = async () => {
      setLoading(true);
      const result = await analyzeResults(coordinates);

      if (isMounted) {
        setAnalysis(result);
        setLoading(false);
        if (onAnalysisComplete) {
          onAnalysisComplete(result);
        }

        // Report result to the owner (Google Sheet)
        if (!hasReportedRef.current) {
            hasReportedRef.current = true;
            reportResult(coordinates, result, {
              duration: quizDuration,
              answers: answers,
              userName: userName,
              userEmail: userEmail
            });
        }
      }
    };
    fetchAnalysis();
    return () => { isMounted = false; };
  }, [coordinates, initialAnalysis]);

  const handleShare = async () => {
    if (!analysis) return;

    // Construct URL with parameters
    const params = new URLSearchParams();
    params.set('x', coordinates.x.toString());
    params.set('y', coordinates.y.toString());
    params.set('title', encodeURIComponent(analysis.title));
    params.set('desc', encodeURIComponent(analysis.description));

    const shareUrl = `${window.location.origin}${window.location.pathname}?${params.toString()}`;
    const shareData = {
      title: 'המצפן הפוליטי - התוצאה שלי',
      text: `יצא לי "${analysis.title}" במצפן הפוליטי! בדקו את התוצאה שלי:`,
      url: shareUrl
    };

    // Use Web Share API if available (Mobile)
    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      // Fallback to Clipboard API
      try {
        await navigator.clipboard.writeText(shareUrl);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } catch (err) {
        console.error('Failed to copy:', err);
      }
    }
  };

  const handleDownload = async () => {
    if (!resultRef.current) return;
    setDownloading(true);

    try {
      const canvas = await html2canvas(resultRef.current, {
        backgroundColor: isDarkMode ? '#0f172a' : '#f8fafc', // slate-950 or slate-50
        scale: 2, // Better quality
        useCORS: true,
      });

      const image = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.href = image;
      link.download = `political-compass-result-${Date.now()}.png`;
      link.click();
    } catch (err) {
      console.error("Failed to download image:", err);
    } finally {
      setDownloading(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto w-full px-4 py-8 animate-fadeIn">
      <div className="text-center mb-12">
        <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-2 tracking-tight">הפרופיל הפוליטי שלך</h2>
        <p className="text-lg text-slate-600 dark:text-slate-400">ניתוח מעמיק המבוסס על תשובותיך</p>
      </div>

      <div ref={resultRef} className={`grid grid-cols-1 lg:grid-cols-12 gap-8 mb-12 p-4 rounded-3xl ${downloading ? (isDarkMode ? 'bg-slate-950' : 'bg-slate-50') : ''}`}>
        {/* Chart Section */}
        <div className="lg:col-span-7 flex flex-col">
            <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800 p-6 transition-colors duration-300">
                <CompassChart coordinates={coordinates} isDarkMode={isDarkMode} isAccessible={isAccessible} />

                <div className="mt-6 grid grid-cols-2 gap-4">
                    <div className="bg-slate-50 dark:bg-slate-800/50 rounded-xl p-4 border border-slate-200 dark:border-slate-700 flex flex-col items-center">
                        <span className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">ציר כלכלי</span>
                        <div className="text-lg font-bold text-slate-800 dark:text-slate-200">
                             {coordinates.x > 0 ? 'ימין' : 'שמאל'} 
                             <span className="mr-2 text-sm font-normal text-yellow-600 dark:text-yellow-500/80">({Math.abs(coordinates.x).toFixed(1)})</span>
                        </div>
                    </div>
                    <div className="bg-slate-50 dark:bg-slate-800/50 rounded-xl p-4 border border-slate-200 dark:border-slate-700 flex flex-col items-center">
                        <span className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">ציר חברתי</span>
                        <div className="text-lg font-bold text-slate-800 dark:text-slate-200">
                            {coordinates.y > 0 ? 'סמכותני' : 'ליברלי'} 
                            <span className="mr-2 text-sm font-normal text-yellow-600 dark:text-yellow-500/80">({Math.abs(coordinates.y).toFixed(1)})</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        {/* Analysis Section */}
        <div className="lg:col-span-5">
            <div className="h-full bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800 p-8 flex flex-col relative overflow-hidden group transition-colors duration-300">
            {/* Hiding decorative elements in accessible mode */}
            {!isAccessible && (
                <>
                <div className="absolute top-0 right-0 w-full h-1 bg-gradient-to-r from-yellow-500 via-yellow-400 to-yellow-500"></div>
                <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-yellow-400/20 dark:bg-yellow-500/10 rounded-full mix-blend-multiply filter blur-2xl opacity-50 group-hover:scale-150 transition-transform duration-700"></div>
                </>
            )}

            <div className="flex items-center gap-3 mb-6">
                <div className="p-2 bg-slate-100 dark:bg-slate-800 rounded-xl text-yellow-500 dark:text-yellow-400 border border-slate-200 dark:border-slate-700">
                    <Sparkles className="w-5 h-5" />
                </div>
                <h3 className="font-bold text-xl text-slate-800 dark:text-slate-100">ניתוח AI חכם</h3>
            </div>

            {loading ? (
                <div className="flex-1 flex flex-col items-center justify-center text-slate-400 space-y-6" role="status" aria-label="מעבד נתונים">
                    <div className="relative">
                        <div className="w-16 h-16 border-4 border-slate-200 dark:border-slate-800 border-t-yellow-400 rounded-full animate-spin"></div>
                        {!isAccessible && (
                            <div className="absolute inset-0 flex items-center justify-center">
                                <Sparkles className="w-6 h-6 text-yellow-500/50 animate-pulse" />
                            </div>
                        )}
                    </div>
                    <div className="text-center">
                        <p className="text-lg font-medium text-slate-700 dark:text-slate-300">מעבד את הנתונים...</p>
                        <p className="text-sm text-slate-500">הבינה המלאכותית מנסחת את הפרופיל שלך</p>
                    </div>
                </div>
            ) : analysis ? (
                <div className="space-y-6 animate-fadeIn relative z-10">
                <div className="border-b border-slate-200 dark:border-slate-800 pb-4">
                    <span className="text-xs font-bold tracking-wider text-yellow-600 dark:text-yellow-500 uppercase">הגדרה ראשית</span>
                    <h4 className="text-3xl font-black text-slate-900 dark:text-white mt-1 leading-tight">{analysis.title}</h4>
                </div>

                <div>
                    <span className="text-xs font-bold tracking-wider text-slate-500 uppercase">משמעות</span>
                    <p className="text-slate-700 dark:text-slate-300 leading-relaxed mt-2 text-lg">
                    {analysis.description}
                    </p>
                </div>

                </div>
            ) : (
                <div className="text-red-500 dark:text-red-400 flex flex-col items-center justify-center h-full gap-2" role="alert">
                    <AlertCircle className="w-10 h-10" />
                    <p>שגיאה בטעינת הנתונים</p>
                </div>
            )}
            </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row justify-center gap-4">
        {analysis && (
            <>
                <button 
                    onClick={handleShare}
                    className="group relative px-8 py-4 bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-bold rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 transition-all hover:-translate-y-1 hover:shadow-lg overflow-hidden shadow-md flex items-center justify-center gap-3 focus:outline-none focus:ring-4 focus:ring-yellow-400"
                    aria-label="שתף תוצאה"
                >
                    {copied ? (
                        <>
                            <Check className="w-5 h-5 text-green-500" />
                            <span>הקישור הועתק!</span>
                        </>
                    ) : (
                        <>
                            <Share2 className="w-5 h-5" />
                            <span>שתף תוצאה</span>
                        </>
                    )}
                </button>

                <button 
                    onClick={handleDownload}
                    disabled={downloading}
                    className="group relative px-8 py-4 bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-bold rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 transition-all hover:-translate-y-1 hover:shadow-lg overflow-hidden shadow-md flex items-center justify-center gap-3 disabled:opacity-50 focus:outline-none focus:ring-4 focus:ring-yellow-400"
                    aria-label="הורד תמונה"
                >
                    <Download className={`w-5 h-5 ${downloading ? 'animate-bounce' : ''}`} />
                    <span>{downloading ? 'מוריד...' : 'הורד תמונה'}</span>
                </button>
            </>
        )}

        <button 
          onClick={onRetake}
          className="group relative px-8 py-4 bg-yellow-400 text-slate-950 font-bold rounded-xl hover:bg-yellow-300 transition-all hover:-translate-y-1 hover:shadow-lg overflow-hidden shadow-md focus:outline-none focus:ring-4 focus:ring-slate-900 dark:focus:ring-white"
          aria-label="התחל מבחן חדש"
        >
          <div className="flex items-center gap-3 relative z-10">
            <RefreshCw className="w-5 h-5 group-hover:rotate-180 transition-transform duration-500" />
            <span>התחל מבחן חדש</span>
          </div>
        </button>
      </div>
    </div>
  );
};

export default ResultView;

import React, { useState, useMemo } from 'react';
import { ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine, Cell, LabelList } from 'recharts';
import { Coordinates } from '../types';
import { Eye, EyeOff } from 'lucide-react';

interface CompassChartProps {
  coordinates: Coordinates;
  isDarkMode?: boolean;
  isAccessible?: boolean;
}

// Estimated coordinates for major Israeli parties
const PARTIES = [
  { name: 'הליכוד', x: 5, y: 5, color: '#1f5aa5' },
  { name: 'יש עתיד', x: 2, y: -3, color: '#003399' },
  { name: 'הדמוקרטים', x: -5, y: -6, color: '#dc2626' },
  { name: 'הציונות הדתית', x: 6, y: 8, color: '#b45309' },
  { name: 'המחנה הממלכתי', x: 1, y: 2, color: '#2563eb' },
  { name: 'ש״ס', x: -3, y: 6, color: '#000000' },
  { name: 'ישראל ביתנו', x: 7, y: 3, color: '#0c4a6e' },
  { name: 'רע״מ', x: -4, y: -2, color: '#166534' },
  { name: 'זהות', x: 9, y: 1.5, color: '#14b8a6' },
];

const CompassChart: React.FC<CompassChartProps> = ({ coordinates, isDarkMode = false, isAccessible = false }) => {
  const [showParties, setShowParties] = useState(false);

  const data = [{ x: coordinates.x, y: coordinates.y, name: 'אני' }];

  // Calculate closest party
  const closestParty = useMemo(() => {
    if (!coordinates) return null;
    let minDistance = Infinity;
    let closest = null;

    PARTIES.forEach(party => {
      const distance = Math.sqrt(
        Math.pow(party.x - coordinates.x, 2) + 
        Math.pow(party.y - coordinates.y, 2)
      );
      if (distance < minDistance) {
        minDistance = distance;
        closest = party;
      }
    });
    return closest;
  }, [coordinates]);

  // Classic Political Compass Colors (Muted/Pastel versions for background)
  const bgColors = isAccessible ? {
    // High Contrast White/Gray Backgrounds or very distinct light colors
    tl: "#ffffff",
    tr: "#f0f0f0", 
    bl: "#e0e0e0", 
    br: "#ffffff", 
  } : {
    tl: "#fca5a5", // Red-300
    tr: "#93c5fd", // Blue-300
    bl: "#86efac", // Green-300
    br: "#fde047", // Yellow-300
  };

  const axisColor = isAccessible ? "#000000" : "#111827";
  const gridColor = isAccessible ? "rgba(0,0,0,0.5)" : "rgba(255,255,255,0.4)";
  const userDotFill = isAccessible ? "#000000" : "#ef4444";
  const userDotStroke = isAccessible ? "#ffffff" : "#ffffff";
  const userDotRadius = isAccessible ? 9 : 7;
  const strokeWidth = isAccessible ? 3 : 2;

  return (
    <div className="w-full flex flex-col gap-6 items-center">

      {/* Controls Header */}
      <div className="w-full flex justify-between items-center px-2">
        <button 
          onClick={() => setShowParties(!showParties)}
          className={`flex items-center gap-2 text-xs font-bold px-3 py-1.5 rounded-full transition-all border ${
            showParties 
              ? 'bg-slate-800 text-white dark:bg-slate-200 dark:text-slate-900 border-transparent' 
              : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
          }`}
          aria-pressed={showParties}
          aria-label={showParties ? "הסתר השוואה למפלגות" : "הצג השוואה למפלגות"}
        >
          {showParties ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
          {showParties ? 'הסתר מפלגות' : 'השווה למפלגות'}
        </button>

        {showParties && closestParty && (
          <div className="flex items-center gap-2 animate-fadeIn">
            <span className="text-xs text-slate-500 dark:text-slate-400">הכי קרוב אליך:</span>
            <span 
              className="text-xs font-black px-2 py-1 rounded-md text-white shadow-sm"
              style={{ backgroundColor: isAccessible ? '#000' : closestParty.color, border: isAccessible ? '1px solid white' : 'none' }}
            >
              {closestParty.name}
            </span>
          </div>
        )}
      </div>

      {/* Chart Wrapper with External Labels */}
      <div className="relative w-full max-w-[450px] mx-auto pt-6 pb-6 px-8">

        {/* External Labels - Increased size for accessibility */}
        <div className={`absolute top-0 left-0 right-0 text-center font-black ${isAccessible ? 'text-black dark:text-white text-lg' : 'text-slate-700 dark:text-slate-300 text-sm md:text-base'} tracking-wide`}>
          סמכותני (Authoritarian)
        </div>
        <div className={`absolute bottom-0 left-0 right-0 text-center font-black ${isAccessible ? 'text-black dark:text-white text-lg' : 'text-slate-700 dark:text-slate-300 text-sm md:text-base'} tracking-wide`}>
          ליברלי (Libertarian)
        </div>
        <div className="absolute top-0 bottom-0 left-0 flex items-center justify-center w-8">
             <span className={`-rotate-90 text-center font-black ${isAccessible ? 'text-black dark:text-white text-lg' : 'text-slate-700 dark:text-slate-300 text-sm md:text-base'} whitespace-nowrap tracking-wide`}>שמאל (Left)</span>
        </div>
        <div className="absolute top-0 bottom-0 right-0 flex items-center justify-center w-8">
             <span className={`rotate-90 text-center font-black ${isAccessible ? 'text-black dark:text-white text-lg' : 'text-slate-700 dark:text-slate-300 text-sm md:text-base'} whitespace-nowrap tracking-wide`}>ימין (Right)</span>
        </div>

        {/* The Chart Box */}
        <div className={`aspect-square relative border-[3px] shadow-2xl overflow-hidden bg-white ${isAccessible ? 'border-black dark:border-white' : 'border-slate-800 dark:border-slate-400'}`}>

            {/* Colored Backgrounds */}
            <div className="absolute inset-0 grid grid-cols-2 grid-rows-2 opacity-90">
                <div style={{ backgroundColor: bgColors.tl, borderRight: isAccessible ? '1px solid black' : 'none', borderBottom: isAccessible ? '1px solid black' : 'none' }}></div>
                <div style={{ backgroundColor: bgColors.tr, borderLeft: isAccessible ? '1px solid black' : 'none', borderBottom: isAccessible ? '1px solid black' : 'none' }}></div>
                <div style={{ backgroundColor: bgColors.bl, borderRight: isAccessible ? '1px solid black' : 'none', borderTop: isAccessible ? '1px solid black' : 'none' }}></div>
                <div style={{ backgroundColor: bgColors.br, borderLeft: isAccessible ? '1px solid black' : 'none', borderTop: isAccessible ? '1px solid black' : 'none' }}></div>
            </div>

            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart
                margin={{ top: 0, right: 0, bottom: 0, left: 0 }}
              >
                {/* Grid Lines */}
                <CartesianGrid 
                    stroke={gridColor} 
                    strokeWidth={isAccessible ? 1 : 1} 
                />

                <XAxis type="number" dataKey="x" domain={[-10, 10]} tickCount={21} hide />
                <YAxis type="number" dataKey="y" domain={[-10, 10]} tickCount={21} hide />

                {/* Central Axes */}
                <ReferenceLine y={0} stroke={axisColor} strokeWidth={strokeWidth} />
                <ReferenceLine x={0} stroke={axisColor} strokeWidth={strokeWidth} />

                {/* User Position */}
                <Scatter name="Your Position" data={data} zIndex={20}>
                  <Cell fill={userDotFill} stroke={userDotStroke} strokeWidth={2} r={userDotRadius} />
                </Scatter>

                {/* Parties */}
                {showParties && (
                  <Scatter name="Parties" data={PARTIES} zIndex={10}>
                    {PARTIES.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={isAccessible ? (isDarkMode ? '#fff' : '#000') : entry.color} stroke={isAccessible ? (isDarkMode ? '#000' : '#fff') : '#ffffff'} strokeWidth={1} r={isAccessible ? 5 : 4} />
                    ))}
                    <LabelList 
                        dataKey="name" 
                        position="top" 
                        offset={5}
                        style={{ 
                            fill: isAccessible ? (isDarkMode ? '#fff' : '#000') : '#000000', 
                            fontSize: isAccessible ? '12px' : '10px', 
                            fontWeight: '800',
                            textShadow: isAccessible ? 'none' : '0px 0px 4px rgba(255,255,255,0.8)',
                            pointerEvents: 'none'
                        }} 
                    />
                  </Scatter>
                )}

                <Tooltip cursor={{ strokeDasharray: '3 3' }} content={() => null} />
              </ScatterChart>
            </ResponsiveContainer>
        </div>

        {/* Point Annotation */}
        <div className={`absolute bottom-1 right-2 ${isAccessible ? 'text-xs text-black font-bold' : 'text-[9px] text-slate-400 dark:text-slate-500'} font-mono`}>
           ({coordinates.x.toFixed(1)}, {coordinates.y.toFixed(1)})
        </div>
      </div>
    </div>
  );
};

export default CompassChart;

import React, { useState, useEffect } from 'react';
import { Question, Answer } from '../types';
import { QUESTIONS } from '../constants';
import { ArrowLeft, ArrowRight, Check, ChevronRight, X, Minus } from 'lucide-react';

interface QuizProps {
  onComplete: (answers: Answer[]) => void;
}

const Quiz: React.FC<QuizProps> = ({ onComplete }) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Answer[]>([]);
  const [animating, setAnimating] = useState(false);
  const [direction, setDirection] = useState<'forward' | 'backward'>('forward');

  useEffect(() => {
    // Fisher-Yates shuffle algorithm to randomize questions
    const shuffled = [...QUESTIONS];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    setQuestions(shuffled);
  }, []);

  // Wait for shuffle to complete
  if (questions.length === 0) return null;

  // Ensure currentIndex is valid
  const currentQuestion = questions[currentIndex];

  const handleAnswer = (score: number) => {
    if (animating) return; // Prevent double clicks

    const newAnswer: Answer = { questionId: currentQuestion.id, score };

    // Create a copy of answers to modify
    const updatedAnswers = [...answers];
    // Update or insert the answer at the current index
    updatedAnswers[currentIndex] = newAnswer;

    setAnswers(updatedAnswers);
    setDirection('forward');
    setAnimating(true);

    setTimeout(() => {
      if (currentIndex < questions.length - 1) {
        setCurrentIndex(prev => prev + 1);
        setAnimating(false);
      } else {
        // Last question - call onComplete
        try {
          onComplete(updatedAnswers);
        } catch (e) {
          console.error("Error completing quiz:", e);
          setAnimating(false); // Restore UI if error occurs
        }
      }
    }, 250);
  };

  const handleBack = () => {
    if (currentIndex > 0 && !animating) {
      setDirection('backward');
      setAnimating(true);
      setTimeout(() => {
        setCurrentIndex(prev => prev - 1);
        setAnimating(false);
      }, 250);
    }
  };

  // Safe progress calculation
  const progress = Math.min(100, Math.round(((currentIndex + 1) / questions.length) * 100));

  return (
    <div className="max-w-4xl mx-auto w-full px-4" role="main" aria-label="מבחן המצפן הפוליטי">
      {/* Progress Bar */}
      <div className="mb-8" role="progressbar" aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100} aria-label="התקדמות במבחן">
        <div className="flex justify-between items-end text-sm text-slate-500 dark:text-slate-400 mb-3 font-medium">
          <div className="flex flex-col">
            <span className="text-xs text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-1">התקדמות</span>
            <span className="text-xl font-bold text-yellow-500 dark:text-yellow-400">שאלה {currentIndex + 1} <span className="text-slate-500 dark:text-slate-600 text-base font-normal">/ {questions.length}</span></span>
          </div>
          <div className="bg-white dark:bg-slate-800 px-3 py-1 rounded-full shadow-sm border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 transition-colors">
             {progress}%
          </div>
        </div>
        <div className="h-4 w-full bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden border border-slate-300 dark:border-slate-700">
          <div 
            className="h-full bg-yellow-400 transition-all duration-500 ease-out rounded-full shadow-[0_0_10px_rgba(250,204,21,0.5)]"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* Question Card */}
      <div className={`transform transition-all duration-300 ease-out ${
          animating 
            ? (direction === 'forward' ? 'opacity-0 -translate-x-10' : 'opacity-0 translate-x-10') 
            : 'opacity-100 translate-x-0'
        }`}>
        <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl rounded-3xl shadow-xl p-8 md:p-12 mb-8 border border-slate-200 dark:border-slate-800 min-h-[200px] md:min-h-[240px] flex flex-col justify-center items-center text-center relative overflow-hidden group transition-colors duration-300">
           {/* Subtle background decoration */}
           <div className="absolute top-0 right-0 w-32 h-32 bg-yellow-400/10 dark:bg-yellow-500/5 rounded-bl-full -mr-10 -mt-10 transition-transform group-hover:scale-110"></div>
           <div className="absolute bottom-0 left-0 w-24 h-24 bg-slate-200/50 dark:bg-slate-700/10 rounded-tr-full -ml-8 -mb-8 transition-transform group-hover:scale-110"></div>

           <h2 className="text-2xl md:text-3xl font-bold text-slate-900 dark:text-slate-100 leading-relaxed z-10 transition-colors" role="heading" aria-level={2}>
            {currentQuestion.text}
          </h2>
        </div>

        {/* Answer Buttons */}
        <div className="grid grid-cols-1 md:grid-cols-5 gap-3 md:gap-4 w-full" role="group" aria-label="אפשרויות תשובה">

          {/* Strongly Agree (+2) */}
          <button 
            onClick={() => handleAnswer(2)}
            disabled={animating}
            aria-label="מסכים בהחלט"
            className="group relative h-20 md:h-40 rounded-2xl bg-gradient-to-br from-green-500 to-green-600 text-white hover:from-green-400 hover:to-green-500 transition-all shadow-lg hover:shadow-green-500/25 hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 overflow-hidden border border-green-500 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-green-400 focus:outline-none"
          >
            <div className="flex md:flex-col items-center gap-2 md:gap-3">
               <Check className="w-6 h-6 md:w-10 md:h-10 stroke-[3]" />
               <span className="text-lg font-bold leading-tight">מסכים<br className="hidden md:block"/> בהחלט</span>
            </div>
          </button>

          {/* Agree (+1) */}
          <button 
            onClick={() => handleAnswer(1)}
            disabled={animating}
            aria-label="מסכים"
            className="group h-16 md:h-40 rounded-2xl bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300 hover:bg-green-100 dark:hover:bg-green-900/30 border-2 border-green-200 dark:border-green-800 hover:border-green-300 transition-all shadow-sm hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-green-300 focus:outline-none"
          >
             <div className="flex md:flex-col items-center gap-2">
                <Check className="w-5 h-5 md:w-6 md:h-6" />
                <span className="font-bold text-base md:text-lg">מסכים</span>
             </div>
          </button>

          {/* Neutral (0) */}
          <button 
            onClick={() => handleAnswer(0)}
            disabled={animating}
            aria-label="ניטרלי"
            className="group h-14 md:h-40 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-700 border-2 border-slate-200 dark:border-slate-700 hover:border-slate-300 transition-all shadow-sm hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-slate-300 focus:outline-none"
          >
             <div className="flex md:flex-col items-center gap-2">
                <Minus className="w-5 h-5 md:w-6 md:h-6" />
                <span className="font-medium text-base md:text-lg">ניטרלי</span>
             </div>
          </button>

          {/* Disagree (-1) */}
          <button 
            onClick={() => handleAnswer(-1)}
            disabled={animating}
            aria-label="לא מסכים"
            className="group h-16 md:h-40 rounded-2xl bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 hover:bg-red-100 dark:hover:bg-red-900/30 border-2 border-red-200 dark:border-red-800 hover:border-red-300 transition-all shadow-sm hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-red-300 focus:outline-none"
          >
             <div className="flex md:flex-col items-center gap-2">
                <X className="w-5 h-5 md:w-6 md:h-6" />
                <span className="font-bold text-base md:text-lg">לא מסכים</span>
             </div>
          </button>

          {/* Strongly Disagree (-2) */}
          <button 
            onClick={() => handleAnswer(-2)}
            disabled={animating}
            aria-label="מתנגד בהחלט"
            className="group relative h-20 md:h-40 rounded-2xl bg-gradient-to-br from-red-500 to-red-600 text-white hover:from-red-400 hover:to-red-500 transition-all shadow-lg hover:shadow-red-500/25 hover:-translate-y-1 active:scale-95 flex md:flex-col items-center justify-between md:justify-center px-6 md:px-2 gap-2 overflow-hidden border border-red-500 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none focus:ring-4 focus:ring-red-400 focus:outline-none"
          >
             <div className="flex md:flex-col items-center gap-2 md:gap-3">
                <X className="w-6 h-6 md:w-10 md:h-10 stroke-[3]" />
                <span className="text-lg font-bold leading-tight">מתנגד<br className="hidden md:block"/> בהחלט</span>
             </div>
          </button>
        </div>

        {/* Navigation Controls */}
        <div className="mt-8 flex justify-center md:justify-start px-2">
            <button
                onClick={handleBack}
                disabled={currentIndex === 0 || animating}
                aria-label="חזור לשאלה הקודמת"
                className={`flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-all focus:outline-none focus:ring-4 focus:ring-slate-400 ${
                    currentIndex === 0 || animating
                    ? 'text-slate-300 dark:text-slate-700 cursor-not-allowed opacity-50' 
                    : 'text-slate-500 hover:text-yellow-600 dark:text-slate-400 dark:hover:text-yellow-400 hover:bg-slate-100 dark:hover:bg-slate-800'
                }`}
            >
                <ChevronRight className="w-5 h-5 rotate-180" /> 
                <span>חזור לשאלה הקודמת</span>
            </button>
        </div>

      </div>
    </div>
  );
};

export default Quiz;

import React, { useState, useMemo } from 'react';
import { ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine, Cell, LabelList } from 'recharts';
import { Coordinates } from '../types';
import { Eye, EyeOff } from 'lucide-react';

interface CompassChartProps {
  coordinates: Coordinates;
  isDarkMode?: boolean;
  isAccessible?: boolean;
  hideControls?: boolean;
}

// Estimated coordinates for major Israeli parties
const PARTIES = [
  { name: 'הליכוד', x: 5, y: 5, color: '#1f5aa5' },
  { name: 'יש עתיד', x: 2, y: -3, color: '#003399' },
  { name: 'הדמוקרטים', x: -5, y: -6, color: '#dc2626' },
  { name: 'הציונות הדתית', x: 6, y: 8, color: '#b45309' },
  { name: 'המחנה הממלכתי', x: 1, y: 2, color: '#2563eb' },
  { name: 'ש״ס', x: -3, y: 6, color: '#000000' },
  { name: 'ישראל ביתנו', x: 7, y: 3, color: '#0c4a6e' },
  { name: 'רע״מ', x: -4, y: -2, color: '#166534' },
  { name: 'זהות', x: 9, y: 1.5, color: '#14b8a6' },
];

const CompassChart: React.FC<CompassChartProps> = ({ coordinates, isDarkMode = false, isAccessible = false, hideControls = false }) => {
  const [showParties, setShowParties] = useState(false);

  const data = [{ x: coordinates.x, y: coordinates.y, name: 'אני' }];

  // Calculate closest party
  const closestParty = useMemo(() => {
    if (!coordinates) return null;
    let minDistance = Infinity;
    let closest = null;

    PARTIES.forEach(party => {
      const distance = Math.sqrt(
        Math.pow(party.x - coordinates.x, 2) + 
        Math.pow(party.y - coordinates.y, 2)
      );
      if (distance < minDistance) {
        minDistance = distance;
        closest = party;
      }
    });
    return closest;
  }, [coordinates]);

  // Classic Political Compass Colors (Muted/Pastel versions for background)
  const bgColors = isAccessible ? {
    // High Contrast White/Gray Backgrounds or very distinct light colors
    tl: "#ffffff",
    tr: "#f0f0f0", 
    bl: "#e0e0e0", 
    br: "#ffffff", 
  } : {
    tl: "#fca5a5", // Red-300 (Auth Left)
    tr: "#93c5fd", // Blue-300 (Auth Right)
    bl: "#86efac", // Green-300 (Lib Left)
    br: "#fde047", // Yellow-300 (Lib Right)
  };

  const axisColor = isAccessible ? "#000000" : "#111827";
  const gridColor = isAccessible ? "rgba(0,0,0,0.5)" : "rgba(255,255,255,0.4)";
  const userDotFill = isAccessible ? "#000000" : "#ef4444";
  const userDotStroke = isAccessible ? "#ffffff" : "#ffffff";
  const userDotRadius = isAccessible ? 9 : 7;
  const strokeWidth = isAccessible ? 3 : 2;

  return (
    <div className="w-full flex flex-col gap-6 items-center">

      {/* Controls Header - Hidden in export mode */}
      {!hideControls && (
        <div className="w-full flex justify-between items-center px-2">
          <button 
            onClick={() => setShowParties(!showParties)}
            className={`flex items-center gap-2 text-xs font-bold px-3 py-1.5 rounded-full transition-all border ${
              showParties 
                ? 'bg-slate-800 text-white dark:bg-slate-200 dark:text-slate-900 border-transparent' 
                : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
            }`}
            aria-pressed={showParties}
            aria-label={showParties ? "הסתר השוואה למפלגות" : "הצג השוואה למפלגות"}
          >
            {showParties ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
            {showParties ? 'הסתר מפלגות' : 'השווה למפלגות'}
          </button>

          {showParties && closestParty && (
            <div className="flex items-center gap-2 animate-fadeIn">
              <span className="text-xs text-slate-500 dark:text-slate-400">הכי קרוב אליך:</span>
              <span 
                className="text-xs font-black px-2 py-1 rounded-md text-white shadow-sm"
                style={{ backgroundColor: isAccessible ? '#000' : closestParty.color, border: isAccessible ? '1px solid white' : 'none' }}
              >
                {closestParty.name}
              </span>
            </div>
          )}
        </div>
      )}

      {/* Chart Wrapper with External Labels */}
      <div className="relative w-full max-w-[450px] mx-auto pt-6 pb-6 px-8">

        {/* External Labels - Increased size for accessibility */}
        <div className={`absolute top-0 left-0 right-0 text-center font-black ${isAccessible ? 'text-black dark:text-white text-lg' : 'text-slate-700 dark:text-slate-300 text-sm md:text-base'} tracking-wide`}>
          סמכותני (Authoritarian)
        </div>
        <div className={`absolute bottom-0 left-0 right-0 text-center font-black ${isAccessible ? 'text-black dark:text-white text-lg' : 'text-slate-700 dark:text-slate-300 text-sm md:text-base'} tracking-wide`}>
          ליברלי (Libertarian)
        </div>
        <div className="absolute top-0 bottom-0 left-0 flex items-center justify-center w-8">
             <span className={`-rotate-90 text-center font-black ${isAccessible ? 'text-black dark:text-white text-lg' : 'text-slate-700 dark:text-slate-300 text-sm md:text-base'} whitespace-nowrap tracking-wide`}>שמאל (Left)</span>
        </div>
        <div className="absolute top-0 bottom-0 right-0 flex items-center justify-center w-8">
             <span className={`rotate-90 text-center font-black ${isAccessible ? 'text-black dark:text-white text-lg' : 'text-slate-700 dark:text-slate-300 text-sm md:text-base'} whitespace-nowrap tracking-wide`}>ימין (Right)</span>
        </div>

        {/* The Chart Box */}
        <div className={`aspect-square relative border-[3px] shadow-2xl overflow-hidden bg-white ${isAccessible ? 'border-black dark:border-white' : 'border-slate-800 dark:border-slate-400'}`}>

            {/* Colored Backgrounds - Forced LTR to fix mirror issue in RTL document */}
            <div className="absolute inset-0 grid grid-cols-2 grid-rows-2 opacity-90" dir="ltr">
                <div style={{ backgroundColor: bgColors.tl, borderRight: isAccessible ? '1px solid black' : 'none', borderBottom: isAccessible ? '1px solid black' : 'none' }}></div>
                <div style={{ backgroundColor: bgColors.tr, borderLeft: isAccessible ? '1px solid black' : 'none', borderBottom: isAccessible ? '1px solid black' : 'none' }}></div>
                <div style={{ backgroundColor: bgColors.bl, borderRight: isAccessible ? '1px solid black' : 'none', borderTop: isAccessible ? '1px solid black' : 'none' }}></div>
                <div style={{ backgroundColor: bgColors.br, borderLeft: isAccessible ? '1px solid black' : 'none', borderTop: isAccessible ? '1px solid black' : 'none' }}></div>
            </div>

            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart
                margin={{ top: 0, right: 0, bottom: 0, left: 0 }}
              >
                {/* Grid Lines */}
                <CartesianGrid 
                    stroke={gridColor} 
                    strokeWidth={isAccessible ? 1 : 1} 
                />

                <XAxis type="number" dataKey="x" domain={[-10, 10]} tickCount={21} hide />
                <YAxis type="number" dataKey="y" domain={[-10, 10]} tickCount={21} hide />

                {/* Central Axes */}
                <ReferenceLine y={0} stroke={axisColor} strokeWidth={strokeWidth} />
                <ReferenceLine x={0} stroke={axisColor} strokeWidth={strokeWidth} />

                {/* User Position */}
                <Scatter name="Your Position" data={data} zIndex={20}>
                  <Cell fill={userDotFill} stroke={userDotStroke} strokeWidth={2} r={userDotRadius} />
                </Scatter>

                {/* Parties */}
                {showParties && (
                  <Scatter name="Parties" data={PARTIES} zIndex={10}>
                    {PARTIES.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={isAccessible ? (isDarkMode ? '#fff' : '#000') : entry.color} stroke={isAccessible ? (isDarkMode ? '#000' : '#fff') : '#ffffff'} strokeWidth={1} r={isAccessible ? 5 : 4} />
                    ))}
                    <LabelList 
                        dataKey="name" 
                        position="top" 
                        offset={5}
                        style={{ 
                            fill: isAccessible ? (isDarkMode ? '#fff' : '#000') : '#000000', 
                            fontSize: isAccessible ? '12px' : '10px', 
                            fontWeight: '800',
                            textShadow: isAccessible ? 'none' : '0px 0px 4px rgba(255,255,255,0.8)',
                            pointerEvents: 'none'
                        }} 
                    />
                  </Scatter>
                )}

                <Tooltip cursor={{ strokeDasharray: '3 3' }} content={() => null} />
              </ScatterChart>
            </ResponsiveContainer>
        </div>

        {/* Point Annotation */}
        <div className={`absolute bottom-1 right-2 ${isAccessible ? 'text-xs text-black font-bold' : 'text-[9px] text-slate-400 dark:text-slate-500'} font-mono`}>
           ({coordinates.x.toFixed(1)}, {coordinates.y.toFixed(1)})
        </div>
      </div>
    </div>
  );
};

export default CompassChart;

import React, { useEffect, useState, useRef } from 'react';
import { Coordinates, AnalysisResult, Answer } from '../types';
import CompassChart from './CompassChart';
import { analyzeResults } from '../services/geminiService';
import { reportResult } from '../services/reportingService';
import { RefreshCw, Sparkles, AlertCircle, Share2, Check, Download, Compass } from 'lucide-react';
import html2canvas from 'html2canvas';

interface ResultViewProps {
  coordinates: Coordinates;
  onRetake: () => void;
  initialAnalysis?: AnalysisResult | null;
  onAnalysisComplete?: (analysis: AnalysisResult) => void;
  isDarkMode?: boolean;
  isAccessible?: boolean;
  // Analytics and User Data
  quizDuration?: number;
  answers?: Answer[];
  userName?: string;
  userEmail?: string;
}

const ResultView: React.FC<ResultViewProps> = ({ 
  coordinates, 
  onRetake, 
  initialAnalysis = null, 
  onAnalysisComplete,
  isDarkMode = false,
  isAccessible = false,
  quizDuration = 0,
  answers = [],
  userName = "Anonymous",
  userEmail = ""
}) => {
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(initialAnalysis);
  const [loading, setLoading] = useState(!initialAnalysis);
  const [copied, setCopied] = useState(false);
  const [downloading, setDownloading] = useState(false);

  // Ref for the visible result view (optional use)
  const resultRef = useRef<HTMLDivElement>(null);

  // Ref for the dedicated export view (hidden from user)
  const exportRef = useRef<HTMLDivElement>(null);

  // Use a ref to ensure we only report once per mounting/calculation
  const hasReportedRef = useRef(false);

  useEffect(() => {
    // If we loaded from history (initialAnalysis exists), we don't report again.
    if (initialAnalysis) {
      setAnalysis(initialAnalysis);
      setLoading(false);
      return;
    }

    let isMounted = true;
    const fetchAnalysis = async () => {
      setLoading(true);
      const result = await analyzeResults(coordinates);

      if (isMounted) {
        setAnalysis(result);
        setLoading(false);
        if (onAnalysisComplete) {
          onAnalysisComplete(result);
        }

        // Report result to the owner (Google Sheet)
        if (!hasReportedRef.current) {
            hasReportedRef.current = true;
            reportResult(coordinates, result, {
              duration: quizDuration,
              answers: answers,
              userName: userName,
              userEmail: userEmail
            });
        }
      }
    };
    fetchAnalysis();
    return () => { isMounted = false; };
  }, [coordinates, initialAnalysis]);

  const handleShare = async () => {
    if (!analysis) return;

    // Construct URL with parameters
    const params = new URLSearchParams();
    params.set('x', coordinates.x.toString());
    params.set('y', coordinates.y.toString());
    params.set('title', encodeURIComponent(analysis.title));
    params.set('desc', encodeURIComponent(analysis.description));

    const shareUrl = `${window.location.origin}${window.location.pathname}?${params.toString()}`;
    const shareData = {
      title: 'המצפן הפוליטי - התוצאה שלי',
      text: `יצא לי "${analysis.title}" במצפן הפוליטי! בדקו את התוצאה שלי:`,
      url: shareUrl
    };

    // Use Web Share API if available (Mobile)
    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.log('Error sharing:', err);
      }
    } else {
      // Fallback to Clipboard API
      try {
        await navigator.clipboard.writeText(shareUrl);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } catch (err) {
        console.error('Failed to copy:', err);
      }
    }
  };

  const handleDownload = async () => {
    // Target the specific export layout
    if (!exportRef.current) return;
    setDownloading(true);

    try {
      // Create canvas from the hidden export ref
      const canvas = await html2canvas(exportRef.current, {
        backgroundColor: '#ffffff', // Always white for clean export
        scale: 2, // High resolution
        useCORS: true,
        logging: false,
        width: 800, // Fixed width for consistency
        windowWidth: 1000 // Ensure layout doesn't break
      });

      const image = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.href = image;
      link.download = `political-compass-result-${Date.now()}.png`;
      link.click();
    } catch (err) {
