export enum Axis {
  ECONOMIC = 'economic', // X-axis: -10 (Left) to +10 (Right)
  SOCIAL = 'social',     // Y-axis: -10 (Libertarian) to +10 (Authoritarian)
}

export interface Question {
  id: number;
  text: string;
  axis: Axis;
  direction: 1 | -1; // 1 means Agreement moves towards Positive (Right/Auth), -1 means Agreement moves towards Negative (Left/Lib)
}

export interface Answer {
  questionId: number;
  score: number; // -2 (Strongly Disagree) to +2 (Strongly Agree)
}

export interface Coordinates {
  x: number;
  y: number;
}

export interface AnalysisResult {
  title: string;
  description: string;
  ideology: string;
  // New detailed fields
  economicAnalysis: string;
  nationalAnalysis: string;
  religiousAnalysis: string;
}

export interface SavedResult {
  coordinates: Coordinates;
  analysis: AnalysisResult;
  timestamp: number;
  userName?: string;
  userEmail?: string;
}

import { SavedResult } from '../types';

const STORAGE_KEY = 'political_compass_result_v1';
const USER_DETAILS_KEY = 'political_compass_user_details_v1';

export const saveResult = (result: SavedResult): void => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(result));

    // Also save user details separately for quick access on registration screen
    if (result.userName) {
        const userDetails = { name: result.userName, email: result.userEmail };
        localStorage.setItem(USER_DETAILS_KEY, JSON.stringify(userDetails));
    }
  } catch (error) {
    console.error('Failed to save result:', error);
  }
};

export const getSavedResult = (): SavedResult | null => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    if (!data) return null;
    return JSON.parse(data) as SavedResult;
  } catch (error) {
    console.error('Failed to load result:', error);
    return null;
  }
};

export const getSavedUserDetails = (): { name: string, email: string } | null => {
    try {
        const data = localStorage.getItem(USER_DETAILS_KEY);
        if (!data) return null;
        return JSON.parse(data);
    } catch (error) {
        return null;
    }
}

export const hasSavedResult = (): boolean => {
  return !!localStorage.getItem(STORAGE_KEY);
};

export const clearSavedResult = (): void => {
  localStorage.removeItem(STORAGE_KEY);
  // We strictly do NOT clear user details here, so they don't have to re-type name next time
};

import { Coordinates, AnalysisResult, Answer } from "../types";

interface AnalyticsData {
  duration: number;
  answers: Answer[];
  userName: string;
  userEmail: string;
  comparedWith?: string; // Name of the friend they compared against
}

export const reportResult = async (coords: Coordinates, analysis: AnalysisResult, extraData?: AnalyticsData) => {
  // This URL should be your Google Apps Script Web App URL
  const reportingUrl = process.env.REPORTING_URL;

  if (!reportingUrl) {
    console.warn("Reporting URL is not configured");
    return;
  }

  console.log("Attempting to report results to Google Sheets...");

  try {
    // Format answers into a compact string like "1:2, 2:-1, 3:0" (QuestionID : Score)
    const answersString = extraData?.answers
      ? extraData.answers.map(a => `${a.questionId}:${a.score}`).join(', ')
      : "";

    const payload = {
      timestamp: new Date().toISOString(),
      userName: extraData?.userName || "Anonymous",
      userEmail: extraData?.userEmail || "",        
      comparedWith: extraData?.comparedWith || "", // New Field sent to sheet
      x: coords.x,
      y: coords.y,
      title: analysis.title,
      description: analysis.description ? analysis.description.substring(0, 500) : "",
      userAgent: navigator.userAgent,
      duration: extraData?.duration || 0,
      answers: answersString,
      screenResolution: `${window.innerWidth}x${window.innerHeight}`
    };

    // Google Apps Script Web Apps have strict CORS policies.
    // We use 'no-cors' which allows the request to be sent, but we cannot read the response.
    // CRITICAL: We MUST use 'text/plain' as Content-Type for the body to be sent correctly in no-cors mode.
    // The Google Script blindly parses the postData.contents, so this works perfectly.
    await fetch(reportingUrl, {
      method: 'POST',
      mode: 'no-cors',
      headers: {
        'Content-Type': 'text/plain',
      },
      body: JSON.stringify(payload),
    });

    console.log("Result report sent successfully (no-cors mode). Please check your Google Sheet.");
  } catch (error) {
    console.error("Reporting failed with error:", error);
  }
};

import React, { useState, useMemo } from 'react';
