function doPost(e) {
  try {
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();

    // Parse the data sent from the app
    var data = JSON.parse(e.postData.contents);

    // Add headers if sheet is empty (כולל העמודות החדשות)
    if (sheet.getLastRow() === 0) {
      sheet.appendRow([
        "Timestamp", "Name", "Email", "Compared With", 
        "X", "Y", "Quadrant", "Distance From Center", "Title", "Description", 
        "Duration (Sec)", "Answers", 
        "Referrer", "UTM Source", "Device Type", "Language", "Screen Res", "User Agent", "Platform"
      ]);
    }

    // Add the row data matching the headers
    sheet.appendRow([
      data.timestamp,
      data.userName,
      data.userEmail,
      data.comparedWith,
      data.x,
      data.y,
      data.quadrant, // New
      data.distanceFromCenter, // New
      data.title,
      data.description,
      data.duration,
      data.answers,
      data.referrer, // New
      data.utm_source, // New
      data.deviceType, // New
      data.language, // New
      data.screenResolution,
      data.userAgent,
      data.platform // New
    ]);

    return ContentService.createTextOutput(JSON.stringify({"status": "success"}))
      .setMimeType(ContentService.MimeType.JSON);

  } catch(error) {
    return ContentService.createTextOutput(JSON.stringify({"status": "error", "message": error.toString()}))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

